let app={calibrated:false,calibration:{level:'A0',style:'logic',goal:'biomedical'},xp:0,index:0,states:{},mastery:{},skillStats:{},stats:{opened:0,streak:0,failed:0},profile:{style:'logic',goal:'biomedical',mode:'type',dept:'genel',theme:'krem',musicRegion:'mix',voice:'default',speed:.85,autoSpeak:false,prefillPercent:25,rewardMode:'every',autoUpdate:true},cat:'en',quiz:{},badges:[],inbox:[],levelFloor:null,updatedAt:0};
