// ---- Kalıcı kayıt (telefonda) ----
// 1) localStorage: anında açılış. 2) Platform.storage (Preferences): işletim sisteminin silmediği kopya.
function mergeState(v){if(!v||typeof v!=='object')return false;app={...app,...v,profile:{...app.profile,...(v.profile||{})},stats:{...app.stats,...(v.stats||{})},calibration:{...app.calibration,...(v.calibration||{})},states:v.states||{},mastery:v.mastery||{},skillStats:v.skillStats||{}};if(!Number.isInteger(app.index)||app.index<0||app.index>=questions.length)app.index=0;sanitizeState();return true}
// Yedek dosyası dışarıdan gelebilir: türleri düzelt, beklenmeyen değerleri at.
function sanitizeState(){const n=(v,d=0)=>Number.isFinite(Number(v))&&Number(v)>=0?Number(v):d;app.xp=n(app.xp);if(app.levelFloor!=null){const f=Math.floor(n(app.levelFloor));app.levelFloor=f>=0&&f<LEVELS.length?f:0}const strObj=o=>o&&typeof o==='object'&&!Array.isArray(o);app.inbox=(Array.isArray(app.inbox)?app.inbox:[]).filter(strObj).slice(0,40).map(m=>({icon:String(m.icon||'✉️').slice(0,8),title:String(m.title||'').slice(0,120),text:String(m.text||'').slice(0,600),at:n(m.at,Date.now())}));app.badges=(Array.isArray(app.badges)?app.badges:[]).filter(strObj).slice(0,60).map(b=>({emoji:String(b.emoji||'🏅').slice(0,8),title:String(b.title||'').slice(0,120),at:n(b.at,Date.now())}));for(const k of ['states','mastery','skillStats'])if(!strObj(app[k]))app[k]={};if(!strObj(app.profile))app.profile={};for(const [k,v] of Object.entries(app.profile))if(v!=null&&typeof v==='object')delete app.profile[k];if(app.quiz!=null&&!strObj(app.quiz))app.quiz={};if(app.quiz){for(const k of ['items','catXp','cur'])if(app.quiz[k]!=null&&!strObj(app.quiz[k]))app.quiz[k]={};if(app.quiz.recent!=null&&!Array.isArray(app.quiz.recent))app.quiz.recent=[]}}
function loadLocal(){try{const v=JSON.parse(localStorage.getItem(STORAGE)||localStorage.getItem('english-quest-v3')||'null');mergeState(v)}catch{}}
async function loadDurable(){try{const raw=await Platform.storage.get(STORAGE);if(!raw)return false;const v=JSON.parse(raw);if(v&&typeof v==='object'&&(Number(v.updatedAt)||0)>(Number(app.updatedAt)||0)){mergeState(v);return true}}catch(e){console.warn('[storage] durable load failed',e)}return false}
let durableTimer=null,durablePending=false;
function setSaveStatus(text){const el=$('#saveStatus');if(el)el.textContent=text}
function flushDurable(){if(!durablePending)return Promise.resolve();durablePending=false;clearTimeout(durableTimer);return Platform.storage.set(STORAGE,JSON.stringify(app)).catch(()=>setSaveStatus('Kalıcı kayıt yazılamadı; cihaz depolama alanını kontrol et.'))}
function saveLocal(touch=true){if(touch)app.updatedAt=Date.now();const json=JSON.stringify(app);try{localStorage.setItem(STORAGE,json);setSaveStatus('Kaydedildi · '+new Date(app.updatedAt||Date.now()).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'}))}catch{setSaveStatus('Hızlı kayıt alanı dolu; kalıcı kayıt kullanılıyor.')}durablePending=true;clearTimeout(durableTimer);durableTimer=setTimeout(flushDurable,touch?400:1500);if(touch)cloud.pushStats()}
function fillDeptSelect(sel,value){if(!sel)return;sel.innerHTML=deptOptions().map(d=>`<option value="${d.id}">${esc(d.label)}</option>`).join('');sel.value=value||'genel'}
